<?php
// One schema source generates SQLite local/test and MySQL final schema.
function schema(string $driver):array{
 $id=$driver==='mysql'?'BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY':'INTEGER PRIMARY KEY AUTOINCREMENT';$fk=$driver==='mysql'?'BIGINT UNSIGNED':'INTEGER';$tail=$driver==='mysql'?' ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci':'';
 $tables=[
 'users'=>"id $id,name VARCHAR(80) NOT NULL,email VARCHAR(254) NOT NULL UNIQUE,password VARCHAR(255) NOT NULL,role VARCHAR(20) NOT NULL DEFAULT 'student',is_active INTEGER NOT NULL DEFAULT 1,auth_version INTEGER NOT NULL DEFAULT 1,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,CHECK(role IN ('student','instructor','admin'))",
 'categories'=>"id $id,name VARCHAR(80) NOT NULL UNIQUE,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL",
 'courses'=>"id $id,instructor_id $fk NOT NULL,category_id $fk NOT NULL,title VARCHAR(150) NOT NULL,description TEXT NOT NULL,cover_key VARCHAR(20) NOT NULL DEFAULT 'default',status VARCHAR(20) NOT NULL DEFAULT 'draft',created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,FOREIGN KEY(instructor_id) REFERENCES users(id) ON DELETE RESTRICT,FOREIGN KEY(category_id) REFERENCES categories(id) ON DELETE RESTRICT,CHECK(status IN ('draft','published','archived'))",
 'chapters'=>"id $id,course_id $fk NOT NULL,title VARCHAR(150) NOT NULL,position INTEGER NOT NULL,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,FOREIGN KEY(course_id) REFERENCES courses(id) ON DELETE CASCADE,CHECK(position>0)",
 'lessons'=>"id $id,chapter_id $fk NOT NULL,title VARCHAR(150) NOT NULL,body TEXT NOT NULL,youtube_video_id VARCHAR(11) NULL,position INTEGER NOT NULL,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,FOREIGN KEY(chapter_id) REFERENCES chapters(id) ON DELETE CASCADE,CHECK(position>0)",
 'enrollments'=>"id $id,user_id $fk NOT NULL,course_id $fk NOT NULL,last_lesson_id $fk NULL,completed_at DATETIME NULL,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,UNIQUE(user_id,course_id),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE RESTRICT,FOREIGN KEY(course_id) REFERENCES courses(id) ON DELETE RESTRICT,FOREIGN KEY(last_lesson_id) REFERENCES lessons(id) ON DELETE RESTRICT",
 'lesson_progress'=>"id $id,user_id $fk NOT NULL,lesson_id $fk NOT NULL,completed_at DATETIME NOT NULL,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,UNIQUE(user_id,lesson_id),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE RESTRICT,FOREIGN KEY(lesson_id) REFERENCES lessons(id) ON DELETE RESTRICT",
 'quizzes'=>"id $id,course_id $fk NOT NULL UNIQUE,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,FOREIGN KEY(course_id) REFERENCES courses(id) ON DELETE CASCADE",
 'questions'=>"id $id,quiz_id $fk NOT NULL,prompt VARCHAR(500) NOT NULL,explanation TEXT NULL,position INTEGER NOT NULL,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,FOREIGN KEY(quiz_id) REFERENCES quizzes(id) ON DELETE CASCADE",
 'answers'=>"id $id,question_id $fk NOT NULL,text VARCHAR(250) NOT NULL,is_correct INTEGER NOT NULL,position INTEGER NOT NULL,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,FOREIGN KEY(question_id) REFERENCES questions(id) ON DELETE CASCADE",
 'quiz_attempts'=>"id $id,user_id $fk NOT NULL,quiz_id $fk NOT NULL,request_id VARCHAR(36) NOT NULL,submission_hash CHAR(64) NOT NULL,correct_count INTEGER NOT NULL,total_questions INTEGER NOT NULL,score_percent DECIMAL(5,2) NOT NULL,passed INTEGER NOT NULL,submitted_at DATETIME NOT NULL,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,UNIQUE(user_id,request_id),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE RESTRICT,FOREIGN KEY(quiz_id) REFERENCES quizzes(id) ON DELETE RESTRICT",
 'quiz_answers'=>"id $id,attempt_id $fk NOT NULL,question_id $fk NOT NULL,answer_id $fk NULL,is_correct INTEGER NOT NULL,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,UNIQUE(attempt_id,question_id),FOREIGN KEY(attempt_id) REFERENCES quiz_attempts(id) ON DELETE RESTRICT,FOREIGN KEY(question_id) REFERENCES questions(id) ON DELETE RESTRICT,FOREIGN KEY(answer_id) REFERENCES answers(id) ON DELETE RESTRICT"
 ];if($driver==='mysql'){$tables['courses'].=',INDEX idx_courses_status_created(status,created_at)';$tables['quiz_attempts'].=',INDEX idx_attempt_user_quiz(user_id,quiz_id)';}$sql=[];foreach($tables as $name=>$cols)$sql[]="CREATE TABLE IF NOT EXISTS $name ($cols)$tail";if($driver==='sqlite'){$sql[]='CREATE INDEX IF NOT EXISTS idx_courses_status_created ON courses(status,created_at)';$sql[]='CREATE INDEX IF NOT EXISTS idx_attempt_user_quiz ON quiz_attempts(user_id,quiz_id)';}return $sql;
}
